package com.typenull.pingdom.place.api;
import com.typenull.pingdom.place.api.dto.review.*; import com.typenull.pingdom.place.application.service.review.PlaceReviewService; import com.typenull.pingdom.shared.security.annotation.*; import com.typenull.pingdom.shared.security.jwt.JwtAuthenticatedUser; import io.swagger.v3.oas.annotations.*; import io.swagger.v3.oas.annotations.tags.Tag; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.Page; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/places/{placeId}/reviews") @RequiredArgsConstructor @Tag(name="Common",description="공통 API") public class PlaceReviewController { private final PlaceReviewService service;
 @PostMapping @AuthenticatedOnly @Operation(summary="장소 리뷰 작성") public ResponseEntity<PlaceReviewResponse> create(@PathVariable Long placeId,@CurrentUser JwtAuthenticatedUser user,@Valid @RequestBody PlaceReviewCreateRequest request){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(user.userId(),placeId,request));}
 @GetMapping @Operation(summary="장소 리뷰 목록 조회") public Page<PlaceReviewResponse> list(@PathVariable Long placeId,@RequestParam(defaultValue="1") int page,@RequestParam(defaultValue="20") int limit){return service.list(placeId,page,limit);}}
